def test_table_layout_cell_paragraphs_stay_separated() -> None:
    """Adjacent paragraphs in a layout-table cell are separated rather than concatenated into one run of text."""
    html = "<table><tr><td><p><b>Alice Example</b></p><p><i>Customer Service</i></p></td><td>Logo</td></tr><tr><td>A</td><td>B</td><td>C</td></tr></table>"
    options = ConversionOptions(compact_tables=True)

    result = convert(html, options)
    assert result.content is None or "**Alice Example***Customer Service*" not in result.content
    assert result.content is not None
    assert "Alice Example" in result.content
    assert result.content is not None
    assert "Customer Service" in result.content
    assert result.content is not None
    assert "Logo" in result.content


def test_table_nested_chain_not_misclassified_as_layout() -> None:
    """A straight chain of one-nested-table-per-cell tables renders as pipe tables, not a broken layout list."""
    html = "<table><tr><td><table><tr><td><table><tr><td>leaf</td></tr></table></td></tr></table></td></tr></table>"

    result = convert(html)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "leaf" in result.content
    assert result.content is not None
    assert "| ---" in result.content


def test_table_nested_in_single_cell_renders_separately() -> None:
    """A table nested in a single-cell row renders as its own table."""
    html = "<table><tr><th>Summary</th></tr><tr><td>Before<table><tr><th>Item</th><th>Amount</th></tr><tr><td>Alpha</td><td>10</td></tr></table></td></tr></table>"

    result = convert(html)
    assert result.content is not None
    assert "| Item  | Amount |" in result.content
    assert result.content is not None
    assert "| Alpha | 10     |" in result.content
    assert result.content is None or "\\|" not in result.content


def test_table_no_thead() -> None:
    """Table without thead uses first row as implied header."""
    html = "<table><tr><td>Product</td><td>Price</td></tr><tr><td>Apple</td><td>1.00</td></tr></table>"

    result = convert(html)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Product" in result.content
    assert result.content is not None
    assert "Price" in result.content
    assert result.content is not None
    assert "Apple" in result.content
    assert result.content is not None
    assert "1.00" in result.content
    assert result.content is not None
    assert "|" in result.content


def test_table_pipe_chars_in_content() -> None:
    """Table cells containing pipe characters are escaped in output."""
    html = "<table><thead><tr><th>Expression</th><th>Result</th></tr></thead><tbody><tr><td>a | b</td><td>true</td></tr></tbody></table>"

    result = convert(html)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Expression" in result.content
    assert result.content is not None
    assert "Result" in result.content
    assert result.content is not None
    assert "true" in result.content


def test_table_ragged_row_fewer_cells_than_header() -> None:
    """A data row with fewer cells than the header is padded to the declared column count."""
    html = "<table><tr><th>A</th><th>B</th><th>C</th></tr><tr><td>1</td><td>2</td></tr></table>"

    result = convert(html)
    assert result.content == "| A | B | C |\n| --- | --- | --- |\n| 1 | 2 |   |\n"


def test_table_ragged_row_more_cells_than_header() -> None:
    """A data row with more cells than the header widens the separator so no cell is silently dropped."""
    html = "<table><tr><th>A</th><th>B</th></tr><tr><td>1</td><td>2</td><td>3</td></tr></table>"

    result = convert(html)
    assert result.content == "| A | B |   |\n| --- | --- | --- |\n| 1 | 2 | 3 |\n"


def test_table_with_alignment() -> None:
    """Table with column alignment attributes."""
    html = '<table><thead><tr><th align="left">Left</th><th align="center">Center</th><th align="right">Right</th></tr></thead><tbody><tr><td>L</td><td>C</td><td>R</td></tr></tbody></table>'

    result = convert(html)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Left" in result.content
    assert result.content is not None
    assert "Center" in result.content
    assert result.content is not None
    assert "Right" in result.content
    assert result.content is not None
    assert "L" in result.content
    assert result.content is not None
    assert "C" in result.content
    assert result.content is not None
    assert "R" in result.content
    assert result.content is not None
    assert "|" in result.content


def test_table_with_colspan() -> None:
    """Table with colspan attribute in a header cell."""
    html = '<table><thead><tr><th colspan="2">Full Name</th></tr></thead><tbody><tr><td>John</td><td>Doe</td></tr></tbody></table>'

    result = convert(html)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Full Name" in result.content
    assert result.content is not None
    assert "John" in result.content
    assert result.content is not None
    assert "Doe" in result.content


def test_tagged_space_not_duplicated() -> None:
    """A whitespace-only inline element contributes exactly one space."""
    html = "<p>A<i> </i>B</p>"

    result = convert(html)
    assert result.content == "A B\n"


def test_unordered_list() -> None:
    """Unordered list."""
    html = "<ul><li>Item 1</li><li>Item 2</li><li>Item 3</li></ul>"

    result = convert(html)
    assert result.content is not None
    assert "- Item 1" in result.content
    assert result.content is not None
    assert "- Item 2" in result.content
    assert result.content is not None
    assert "- Item 3" in result.content
